    || str_starts_with($text,'У чисел нет обязанности объяснять нашу жизнь')
    || str_starts_with($text,'Смысл здесь рождается не в цифрах')
    || str_starts_with($text,'Попробуй на мгновение оставить поиск тайного послания');
   if (!$generated) { continue; }
   $record->update(['title'=>$title,'symbolism'=>$symbolism,'light_side'=>$light,'shadow_side'=>$shadow,'reflection_question'=>$question,'practice'=>$practice]);
  }
 }
}
